-- =============================================================
-- OweNone demo seed v2  –  rich USD mock data
-- =============================================================
-- Seed-owned UUID ranges (never overlaps user-created UUIDs):
--   users       10000000-...-000000000001..8
--   groups      20000000-...-000000000001..5
--   expenses    30000000-...-000000000001..62
--   settlements 40000000-...-000000000001..5
-- User-created rows (random UUIDs) are never touched.
-- =============================================================

-- ── 1. Idempotent cleanup (settlements first, then expenses;
--        expense_splits cascade automatically) ────────────────

DELETE FROM settlements
WHERE id >= '40000000-0000-0000-0000-000000000001'
  AND id <= '40000000-0000-0000-0000-000000000005';

DELETE FROM expenses
WHERE id >= '30000000-0000-0000-0000-000000000001'
  AND id <= '30000000-0000-0000-0000-000000000062';

